WITH topics AS (SELECT l.project_id, l.topic, l.agent_id, max(l.id) AS watermark, count(*) AS n FROM memory.lessons l JOIN memory.lesson_stages ls ON ls.id = l.stage_id AND ls.code IN ('daily','long_term') WHERE l.archived_at IS NULL AND l.topic IS NOT NULL AND l.topic NOT LIKE 'shared:%' AND l.topic NOT LIKE 'verifier:%' AND l.project_id IS NOT NULL GROUP BY l.project_id, l.topic, l.agent_id HAVING count(*) >= 2)
SELECT t.project_id, p.project_path, t.topic, t.agent_id, a.name AS agent_name, t.watermark FROM topics t JOIN projects.projects p ON p.id = t.project_id LEFT JOIN agents.agents a ON a.id = t.agent_id WHERE p.project_path <> '(no project)' AND NOT EXISTS (SELECT 1 FROM memory.skill_drafts d WHERE d.project_id = t.project_id AND d.folder = CASE WHEN a.name IS NULL THEN t.topic ELSE t.topic || '-' || a.name END AND d.lesson_watermark >= t.watermark) ORDER BY t.n DESC, t.watermark DESC LIMIT 1
